USE `kitchenmart_db`;
ALTER TABLE orders ADD COLUMN IF NOT EXISTS delivered_at DATETIME NULL AFTER order_status;
ALTER TABLE return_requests ADD COLUMN IF NOT EXISTS evidence_image VARCHAR(255) NULL AFTER reason,ADD COLUMN IF NOT EXISTS return_carrier VARCHAR(80) NULL AFTER admin_note,ADD COLUMN IF NOT EXISTS return_tracking_number VARCHAR(120) NULL AFTER return_carrier,ADD COLUMN IF NOT EXISTS return_shipped_at DATETIME NULL AFTER return_tracking_number;
CREATE TABLE IF NOT EXISTS return_request_items(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,return_request_id BIGINT UNSIGNED NOT NULL,order_item_id INT UNSIGNED NOT NULL,quantity INT UNSIGNED NOT NULL,refund_amount DECIMAL(10,2) UNSIGNED NOT NULL DEFAULT 0,UNIQUE KEY uq_return_item(return_request_id,order_item_id),CONSTRAINT fk_return_item_request FOREIGN KEY(return_request_id) REFERENCES return_requests(id) ON DELETE CASCADE,CONSTRAINT fk_return_item_order_item FOREIGN KEY(order_item_id) REFERENCES order_items(id) ON DELETE RESTRICT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
